import {
    context
} from '../../index.js';

export {
    createElement,
    generateUUID,
    isChatOpen,
    parseString,
    isTrueBoolean,
    getUniqueArray,
    getChatMembers,
    findCharacter,
    findUser,
    findCharacterFromMessage,
    getDefaultIDRange,
    getFreeDataUid,
    delay,
};

/** @typedef {TomatoLib.UserCharacter} UserCharacter */

/**
 * Creates or populates elements.
 * Anything complex generated by this function should eventually be turned into an HTML template.
 * @param {string|HTMLElement} elem
 * @param {{class?:string; attr?:Object; data?:Object; innerHTML?: string; innerText?: string; append?: HTMLElement[]}} [options]
 */
function createElement(elem, options = {}) {
    const element = typeof elem === 'string' ? document.createElement(elem) : elem;

    for (const [attr, value] of Object.entries(options.attr ?? {})) {
        element.setAttribute(attr, value);
    }

    for (const [key, value] of Object.entries(options.data ?? {})) {
        element.dataset[key] = value;
    }

    const classes = options.class ?? '';

    if (classes.length > 0)
        element.classList.add(...(classes.split(' ')));

    if (options.innerHTML) element.innerHTML = options.innerHTML ?? '';
    if (options.innerText) element.innerText = options.innerText ?? '';
    if (options.append) element.append(...(options.append ?? []));

    return element;
}

/**
 * Creates a UUID like string using either a v4 UUID (if available on the browser) or a timestamp.
 * @param {string?} [suffix]
 * @returns {string} UUID
 */
function generateUUID(suffix = '') {
    const randUUID = self?.crypto?.randomUUID();
    const uuid = !randUUID ? new Date().valueOf().toString() : randUUID.replaceAll('-', '_');

    return `${suffix}_${uuid}`;
}

/**
 * @returns {boolean}
 */
function isChatOpen() {
    const { chatId } = context();

    return !chatId ? false : true;
}

/**
 * Tries to convert an string to a JSON valid type.
 * @param {string} value
 * @returns {any}
 */
function parseString(value) {
    /** @type {any} */
    let parsed;

    try {
        parsed = typeof value === 'string' ? JSON.parse(value) : value;
    } catch (error) {
        parsed = value;

        if (parsed === 'true') parsed = true;
        if (parsed === 'false') parsed = false;
        if (parsed === 'null') parsed = null;
        if (parsed === 'undefined') parsed = undefined;

        const number = Number(parsed);

        if (!isNaN(number) && /\d/.test(parsed)) parsed = number;
    } finally {
        return parsed;
    }
}

/**
 * Checks if a string is a valid truth value.
 * @param {string} arg String to check
 * @returns {boolean} True if the string is true, false otherwise.
 */
function isTrueBoolean(arg) {
    return ['on', 'true', '1'].includes(arg?.trim()?.toLowerCase());
}

/**
 * Deletes all duplicates on an array, optionally accepts a filter.
 * @param {any[]} array
 * @param {(v: any) => boolean} [filter]
 */
function getUniqueArray(array, filter = (v) => true) {
    return new Set(array).values().toArray().filter(filter);
}

/**
 * Gets all active participants in the current chat.
 * @param {Object} [options]
 * @param {boolean} [options.allowMuted]
 * @returns {Character[]}
 */
function getChatMembers({allowMuted = true} = {}) {
    const { characters, characterId, groupId, groups } = context();
    const group = groupId ? groups.find(g => g.id === groupId) : null;
    const disabled = group?.disabled_members || [];

    let members = group ? group.members.map(m => characters.find(c => c.avatar === m)) : [];

    if (!members.length && characterId)
        members.push(characters[characterId]);

    if (!allowMuted && disabled.length)
        return members.filter(m => !disabled.some(d => d === m.avatar));

    return members;
}

/**
 * Searches for a character object.
 * @param {string} search
 * @param {object} [options]
 * @param {boolean} [options.allowAvatar]
 * @param {boolean} [options.is_user]
 * @param {(Character|UserCharacter)[]} [options.members]
 * @return {Character|UserCharacter}
 */
function findCharacter(search, {allowAvatar = true, members = [], is_user = false} = {}) {
    if (is_user) findUser(search);

    const { characters } = context();
    let character;

    if (!members.length)
        members = getChatMembers();

    search = String(search).trim();

    if (allowAvatar) character = members.find(m => m.avatar === search);
    if (allowAvatar && !character) character = characters.find(c => c.avatar === search);

    if (!character) character = members.find(m => m.name === search);
    if (!character) character = characters.find(c => c.name === search);

    return character;
}

/**
 * @param {string|number} mess_id
 * @returns {Character|UserCharacter}
 */
function findCharacterFromMessage(mess_id) {
    const { chat } = context();
    const mes = chat[mess_id] ?? null;

    if (!mes) return null;

    const { force_avatar, original_avatar, is_user } = mes;

    try {
        const url = new URL(force_avatar, window.location.origin);
        const fileName = url?.searchParams.get('file') ?? '';
        let entity;

        if (fileName) entity = findCharacter(fileName, {is_user});
        if (!entity) entity = findCharacter(original_avatar, {is_user});

        return entity ?? null;
    } catch (err) {
        StatUsMaximus.error(err);

        return null;
    }
}

/**
 * Searches for a user persona.
 * @param {string?} [search]
 * @returns {UserCharacter|null}
 */
function findUser(search = '') {
    const { powerUserSettings: power_user } = context();

    if (!search) search = power_user.default_persona;
    if (!search) return null;

    let avatar = search;

    if (!avatar) avatar = Object
        .entries(power_user.personas)
        .map(([avatar, name]) => {return {name, avatar}})
        .find(per => per.name === String(search))
        ?.avatar;

    if (!avatar || !power_user.personas[avatar]) return null;

    const user = {
        name: String(power_user.personas[avatar]),
        avatar: String(avatar),
        description: String(power_user.persona_descriptions[avatar].description || ''),
        is_user: true,
    };

    return user;
}

/**
 * Gets the full range of message IDs.
 * @param {ChatMessage[]} messages
 */
function getDefaultIDRange(messages) {
    return {
        start: 0,
        end: messages.length - 1
    };
}

/** The function checks for keys from 0 up to a defined safe limit (1,000,000) and returns the first available integer that is not used as a key in the data object.
 * @param {Record<string, any>} data
 * @returns {number} The lowest non-negative integer that is not a key in the provided data object. If the data object is empty, it returns 0.
 */
function getFreeDataUid(data = {}) {
    const keys = Object.keys(data);

    if (!keys?.length) return 0;

    const used = new Set(keys);
    const LIMIT = 1_000_000;

    for (let uid = 0; uid < LIMIT; uid++)
        if (!used.has(String(uid))) return uid;
}

/**
 * Creates a timeout to delay code execution.
 * @param {number} time Amount of milliseconds to wait.
 * @returns {Promise<void>}
 */
async function delay(time) {
    return await new Promise((resolve) => setTimeout(resolve, time));
}